import { createCredential, generateIssuerKeyPair } from '@nexusid/sd-jwt/issuer';
import type { SDJWTCredential, RawClaim } from '@nexusid/types';
import type { AUStudentData } from './portal-scraper';
import * as fs from 'fs';
import * as path from 'path';

function loadIssuerPrivateKey(): string {
  // 1. Try env var first (production / Docker secret)
  if (process.env.AU_ISSUER_PRIVATE_KEY) {
    return process.env.AU_ISSUER_PRIVATE_KEY.replace(/\\n/g, '\n');
  }

  // 2. Try PEM file (generated by scripts/generate-issuer-keys.ts)
  const keyPath = path.resolve(__dirname, '../.issuer-private-key.pem');
  if (fs.existsSync(keyPath)) {
    return fs.readFileSync(keyPath, 'utf-8');
  }

  throw new Error(
    'AU issuer private key not found. ' +
      'Set AU_ISSUER_PRIVATE_KEY env var or run scripts/generate-issuer-keys.ts'
  );
}

function deriveEnrollmentStatus(raw: string): 'Active' | 'Inactive' | 'Graduated' | 'Suspended' | 'On Leave' {
  const normalized = raw.toLowerCase().trim();
  if (normalized.includes('active') || normalized.includes('enrolled')) return 'Active';
  if (normalized.includes('graduat')) return 'Graduated';
  if (normalized.includes('suspend')) return 'Suspended';
  if (normalized.includes('leave')) return 'On Leave';
  return 'Inactive';
}

export async function buildCredential(
  auData: AUStudentData,
  userPublicKey: string
): Promise<SDJWTCredential> {
  const privateKey = loadIssuerPrivateKey();

  const alwaysVisibleClaims: Record<string, unknown> = {
    credential_type: 'enrollment',
    issuer_name: 'Air University',
    university: 'Air University Islamabad',
    verified: true,
  };

  const selectiveFields: RawClaim[] = [
    { field: 'name', value: auData.name },
    { field: 'registration_number', value: auData.registration_number },
    { field: 'program', value: auData.program },
    { field: 'department', value: auData.department },
    { field: 'cgpa', value: auData.cgpa },
    { field: 'enrollment_status', value: deriveEnrollmentStatus(auData.enrollment_status) },
    { field: 'batch', value: auData.batch },
    { field: 'semester_count', value: auData.semester_count },
  ];

  const credential = await createCredential({
    claims: selectiveFields,
    alwaysVisibleClaims,
    issuerDID: 'au.edu.pk',
    subject: auData.registration_number,
    issuerPrivateKey: privateKey,
    keyId: 'au-issuer-key-v1',
    expiresInDays: 365,
  });

  // Attach display metadata
  const enriched: SDJWTCredential = {
    ...credential,
    metadata: {
      always_visible_fields: ['credential_type', 'issuer_name', 'university', 'verified'],
      selectively_disclosable_fields: selectiveFields.map((c) => c.field),
      field_labels: {
        credential_type: 'Credential Type',
        issuer_name: 'Issuer',
        university: 'University',
        verified: 'Verified',
        name: 'Full Name',
        registration_number: 'Registration Number',
        program: 'Program',
        department: 'Department',
        cgpa: 'CGPA',
        enrollment_status: 'Enrollment Status',
        batch: 'Batch',
        semester_count: 'Semesters Completed',
      },
    },
  };

  return enriched;
}
